export const paperOutcomeSourceFiles = [
  { label: '论文成果总表', fileName: '论文成果总表-整理后.xlsx' },
  { label: '期刊/会议知识库', fileName: '期刊汇总-内部可看分区与指标-完善版.xlsx' },
]

export const emptyPaperOutcomeFilters: PaperOutcomeFilters = {
  keyword: '',
  resultType: '',
  projectName: '',
  projectOwner: '',
  batch: '',
  paperStatus: '',
  verificationStatus: '',
  matchStatus: '',
}

export const emptyPaperKnowledgeFilters: PaperKnowledgeFilters = {
  keyword: '',
  publisher: '',
  categoryCn: '',
  jcrPartition: '',
  casPartition: '',
}

export function createPaperOutcomeId(prefix = 'P') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`
}

export function clonePaperOutcomes() {
  return paperOutcomeRows.map((paper) => ({ ...paper }))
}

export function clonePaperKnowledge() {
  return paperKnowledgeRows.map((item) => ({ ...item }))
}

function normalizeText(value: unknown) {
  return String(value ?? '')
    .normalize('NFKC')
    .trim()
    .toLowerCase()
    .replace(/[（）()【】[\]{}<>《》,，.。:：;；/\\_|]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

function makeMatchKey(value: unknown) {
  return normalizeText(value).replace(/\s+/g, '')
}

function matchesValue(value: unknown, expected: string) {
  return !expected || String(value ?? '') === String(expected)
}

function uniqueValues<T, K extends keyof T>(rows: T[], key: K) {
  return Array.from(new Set(rows.map((row) => row[key]).filter(Boolean).map(String))).sort((a, b) =>
    a.localeCompare(b, 'zh-Hans-CN'),
  )
}

function buildKnowledgeIndex(knowledge: PaperKnowledge[]) {
  const byName = new Map<string, PaperKnowledge>()
  const byShortName = new Map<string, PaperKnowledge>()

  knowledge.forEach((item) => {
    const nameKey = makeMatchKey(item.name)
    const shortNameKey = makeMatchKey(item.shortName)

    if (nameKey) {
      byName.set(nameKey, item)
    }

    if (shortNameKey) {
      byShortName.set(shortNameKey, item)
    }
  })

  return { byName, byShortName }
}

export function enrichPaperOutcomes(papers: PaperOutcome[], knowledge: PaperKnowledge[]) {
  const index = buildKnowledgeIndex(knowledge)

  return papers.map((paper) => {
    const venueNameKey = makeMatchKey(paper.venueName)
    const shortNameKey = makeMatchKey(paper.venueShortName)
    const matched = (venueNameKey && index.byName.get(venueNameKey)) || (shortNameKey && index.byShortName.get(shortNameKey))

    if (!matched) {
      return {
        ...paper,
        matchStatus: '未匹配',
        matchedBy: '',
        matchedKnowledgeId: '',
        matchedName: '',
        matchConfidence: 0,
      }
    }

    return {
      ...paper,
      matchStatus: '已匹配',
      matchedBy: venueNameKey && makeMatchKey(matched.name) === venueNameKey ? '名称精确匹配' : '简称精确匹配',
      matchedKnowledgeId: matched.id,
      matchedName: matched.name,
      matchConfidence: 100,
    }
  })
}

export function filterPaperOutcomes(papers: PaperOutcome[], filters: PaperOutcomeFilters) {
  const keyword = normalizeText(filters.keyword)

  return papers.filter((paper) => {
    const text = [
      paper.id,
      paper.title,
      paper.resultType,
      paper.venueName,
      paper.venueShortName,
      paper.paperStatus,
      paper.doi,
      paper.authors,
      paper.collegeAuthors,
      paper.projectName,
      paper.projectOwner,
      paper.batch,
      paper.matchedName,
    ]
      .map((value) => normalizeText(value))
      .join(' ')

    return (
      (!keyword || text.includes(keyword)) &&
      matchesValue(paper.resultType, filters.resultType) &&
      matchesValue(paper.projectName, filters.projectName) &&
      matchesValue(paper.projectOwner, filters.projectOwner) &&
      matchesValue(paper.batch, filters.batch) &&
      matchesValue(paper.paperStatus, filters.paperStatus) &&
      matchesValue(paper.verificationStatus, filters.verificationStatus) &&
      matchesValue(paper.matchStatus, filters.matchStatus)
    )
  })
}

export function filterPaperKnowledge(knowledge: PaperKnowledge[], filters: PaperKnowledgeFilters) {
  const keyword = normalizeText(filters.keyword)

  return knowledge.filter((item) => {
    const text = [
      item.name,
      item.shortName,
      item.publisher,
      item.categoryCn,
      item.categoryEn,
      item.issn,
      item.eissn,
      item.jcrPartition,
      item.casPartition,
      item.citeScore,
      item.impactFactor,
    ]
      .map((value) => normalizeText(value))
      .join(' ')

    return (
      (!keyword || text.includes(keyword)) &&
      matchesValue(item.publisher, filters.publisher) &&
      matchesValue(item.categoryCn, filters.categoryCn) &&
      matchesValue(item.jcrPartition, filters.jcrPartition) &&
      matchesValue(item.casPartition, filters.casPartition)
    )
  })
}

export function buildPaperOptions(papers: PaperOutcome[]) {
  return {
    projects: uniqueValues(papers, 'projectName'),
    people: uniqueValues(papers, 'projectOwner'),
    batches: uniqueValues(papers, 'batch'),
    resultTypes: uniqueValues(papers, 'resultType'),
    paperStatuses: uniqueValues(papers, 'paperStatus'),
    verificationStatuses: uniqueValues(papers, 'verificationStatus'),
    matchStatuses: uniqueValues(papers, 'matchStatus'),
  }
}

export function buildPaperKnowledgeOptions(knowledge: PaperKnowledge[]) {
  return {
    publishers: uniqueValues(knowledge, 'publisher'),
    categories: uniqueValues(knowledge, 'categoryCn'),
    jcrPartitions: uniqueValues(knowledge, 'jcrPartition'),
    casPartitions: uniqueValues(knowledge, 'casPartition'),
  }
}

export function buildPaperSummary(papers: PaperOutcome[], knowledgeCount = 0) {
  const journalPapers = papers.filter((paper) => paper.resultType === '期刊论文').length
  const conferencePapers = papers.filter((paper) => paper.resultType === '会议论文').length
  const matched = papers.filter((paper) => paper.matchStatus === '已匹配').length
  const unverified = papers.filter((paper) => paper.verificationStatus === '未核验').length

  return {
    total: papers.length,
    journalPapers,
    conferencePapers,
    matched,
    unmatched: papers.length - matched,
    unverified,
    verified: papers.length - unverified,
    knowledgeCount,
  }
}

export function buildPaperQualityReport(papers: PaperOutcome[]) {
  const titleGroups = new Map<string, PaperOutcome[]>()

  papers.forEach((paper) => {
    const key = makeMatchKey(paper.title)
    if (!key) {
      return
    }
    titleGroups.set(key, [...(titleGroups.get(key) ?? []), paper])
  })

  const issues: PaperQualityIssue[] = []
  const addIssue = (paper: PaperOutcome, type: string, message: string, severity: PaperQualityIssue['severity'] = '中') => {
    issues.push({ id: `${paper.id}-${type}`, paperId: paper.id, title: paper.title, type, message, severity })
  }

  papers.forEach((paper) => {
    if (!paper.title) {
      addIssue(paper, '缺少题名', '论文题目为空', '高')
    }
    if (!paper.venueName) {
      addIssue(paper, '缺少期刊/会议', '发表载体名称为空', '高')
    }
    if (!paper.resultType) {
      addIssue(paper, '缺少成果类型', '成果类型为空', '中')
    }
    if (!paper.projectOwner) {
      addIssue(paper, '缺少负责人', '项目负责人为空', '中')
    }
    if (paper.matchStatus !== '已匹配') {
      addIssue(paper, '未匹配', '未在知识库中匹配到名称或简称', '中')
    }
    if (paper.verificationStatus === '未核验') {
      addIssue(paper, '未核验', '该记录尚未完成核验', '低')
    }
  })

  titleGroups.forEach((group) => {
    if (group.length > 1) {
      group.forEach((paper) => addIssue(paper, '疑似重复', `同题名记录 ${group.length} 条`, '中'))
    }
  })

  const grouped = issues.reduce<Record<string, number>>((acc, issue) => {
    acc[issue.type] = (acc[issue.type] ?? 0) + 1
    return acc
  }, {})

  return {
    summary: {
      papers: papers.length,
      issues: issues.length,
      high: issues.filter((issue) => issue.severity === '高').length,
      medium: issues.filter((issue) => issue.severity === '中').length,
      low: issues.filter((issue) => issue.severity === '低').length,
    },
    grouped,
    issues,
  }
}
